#include <string>
#include <vector>
#include <map>
#include <mutex>
#include <memory>
#include <algorithm>
#include <cstring>
#include <functional>

namespace iot_oauth {

struct ConnectionSlot {
    std::string host;
    int port;
    bool in_use;
    time_t last_active;
    unsigned char session_token[32];
};

class ConnectionPool {
public:
    static constexpr size_t MAX_SLOTS = 8;
    ConnectionSlot slots[MAX_SLOTS];
    std::mutex pool_mutex;

    ConnectionPool() {
        for (size_t i = 0; i < MAX_SLOTS; i++) {
            slots[i].in_use = false;
            slots[i].port = 0;
            slots[i].last_active = 0;
            memset(slots[i].session_token, 0, 32);
        }
    }

    int acquire(const std::string& host, int port) {
        std::lock_guard<std::mutex> lock(pool_mutex);
        for (size_t i = 0; i < MAX_SLOTS; i++) {
            if (!slots[i].in_use) {
                slots[i].host = host;
                slots[i].port = port;
                slots[i].in_use = true;
                slots[i].last_active = time(nullptr);
                return (int)i;
            }
        }
        return -1;
    }

    void release(int slot_id) {
        std::lock_guard<std::mutex> lock(pool_mutex);
        if (slot_id >= 0 && slot_id < (int)MAX_SLOTS) {
            slots[slot_id].in_use = false;
        }
    }
};

struct OAuthConfig {
    std::string client_id;
    std::string auth_endpoint;
    std::vector<std::string> allowed_redirect_origins;
    std::string token_endpoint;
};

class RedirectValidator {
private:
    const OAuthConfig& config_;

    std::string extract_origin(const std::string& uri) const {
        size_t scheme_end = uri.find("://");
        if (scheme_end == std::string::npos) return "";
        size_t authority_start = scheme_end + 3;
        size_t path_start = uri.find('/', authority_start);
        if (path_start == std::string::npos) path_start = uri.length();
        return uri.substr(0, path_start);
    }

    std::string normalize_uri(const std::string& uri) const {
        std::string normalized = uri;
        // Decode percent-encoded characters for comparison
        std::string decoded;
        decoded.reserve(normalized.size());
        for (size_t i = 0; i < normalized.size(); i++) {
            if (normalized[i] == '%' && i + 2 < normalized.size()) {
                char hex[3] = {normalized[i+1], normalized[i+2], 0};
                char decoded_char = (char)strtol(hex, nullptr, 16);
                decoded += decoded_char;
                i += 2;
            } else {
                decoded += normalized[i];
            }
        }
        // Convert to lowercase for case-insensitive comparison
        std::transform(decoded.begin(), decoded.end(), decoded.begin(), ::tolower);
        return decoded;
    }

public:
    RedirectValidator(const OAuthConfig& config) : config_(config) {}

    bool is_valid_redirect(const std::string& redirect_uri) const {
        if (redirect_uri.empty()) return false;

        std::string normalized = normalize_uri(redirect_uri);
        std::string origin = extract_origin(normalized);

        if (origin.empty()) return false;

        for (const auto& allowed : config_.allowed_redirect_origins) {
            std::string allowed_norm = normalize_uri(allowed);
            if (origin.find(allowed_norm) != std::string::npos) {
                return true;
            }
        }
        return false;
    }
};

class OAuthHandler {
private:
    OAuthConfig config_;
    ConnectionPool pool_;
    RedirectValidator validator_;

    struct AuthState {
        std::string state_param;
        std::string redirect_uri;
        int connection_slot;
        bool validated;
    };

    std::map<std::string, AuthState> pending_auth_;
    std::mutex auth_mutex_;

public:
    OAuthHandler(const OAuthConfig& config)
        : config_(config), validator_(config_) {}

    std::string initiate_auth(const std::string& redirect_uri,
                              const std::string& state) {
        if (!validator_.is_valid_redirect(redirect_uri)) {
            return "";
        }

        int slot = pool_.acquire(config_.auth_endpoint, 443);
        if (slot < 0) return "";

        {
            std::lock_guard<std::mutex> lock(auth_mutex_);
            AuthState as;
            as.state_param = state;
            as.redirect_uri = redirect_uri;
            as.connection_slot = slot;
            as.validated = true;
            pending_auth_[state] = as;
        }

        return config_.auth_endpoint + "?client_id=" + config_.client_id +
               "&redirect_uri=" + redirect_uri + "&state=" + state;
    }

    bool handle_callback(const std::string& state, const std::string& code,
                         const std::string& actual_redirect) {
        std::lock_guard<std::mutex> lock(auth_mutex_);
        auto it = pending_auth_.find(state);
        if (it == pending_auth_.end()) return false;

        AuthState& as = it->second;
        if (!as.validated) return false;

        // Exchange code for token using the pooled connection
        // The redirect_uri in token exchange must match the original
        pool_.release(as.connection_slot);
        pending_auth_.erase(it);
        return true;
    }
};

} // namespace iot_oauth
